  $('sweepWeaponNext').addEventListener('click',()=>{if(this.selectWeapon)this.screen('maps')});$('sweepMapNext').addEventListener('click',()=>this.screen('difficulty'));$('sweepBrief').addEventListener('click',()=>this.brief());$('sweepDeploy').addEventListener('click',()=>{unlock();this.audio.unlock(audio);this.start(this.selectMap,this.selectWeapon,selectedDifficulty);preferLandscape()});
  for(const [id,screen]of [['sweepBackHome','home'],['sweepBackWeapons','weapons'],['sweepBackMaps','maps'],['sweepBackDifficulty','difficulty']])$(id).addEventListener('click',()=>screen==='home'?showScreen('home'):this.screen(screen));
  for(const [id,role]of Object.entries(TZClasses.ROLES)){const option=document.createElement('option');option.value=id;option.textContent=role.name;$('sweepClass').appendChild(option)}$('sweepClass').value=ClassUI.selected;$('sweepClass').addEventListener('change',e=>{ClassUI.choose(e.target.value);this.difficultyText()});$('sweepDifficulty').value=selectedDifficulty;$('sweepDifficulty').addEventListener('change',e=>{selectedDifficulty=e.target.value;$('difficulty').value=selectedDifficulty;try{localStorage.setItem('tactical-difficulty',selectedDifficulty)}catch(_){}this.difficultyText()});
