  Expedition.containers=[];for(const f of this.map.floors)for(const dec of f.decorations){const p={x:dec.x+42,y:dec.y,floorId:f.id};if(this.nav.walkable(p))Expedition.containers.push({...p,id:dec.id,name:'建筑档案箱',type:'tech',opened:false,progress:0})}Expedition.bag=[];Expedition.searching=null;Expedition.settled=false;Expedition.load();FieldOps.ops=null;FieldOps.bonus=0;worldGeometry={los:(a,b)=>this.nav.los(a,b),revealed:(a,b)=>this.visible(b),hidden:()=>false,grassAt:()=>false,nearest:(x,y)=>({x,y,floorId:player.floorId})};
