 bulletUpdate(dt){this.refreshActors();for(let i=bullets.length-1;i>=0;i--){const b=bullets[i],speed=Math.hypot(b.vx,b.vy),step=Math.min(speed*dt,b.remaining),end={x:b.x+b.vx/speed*step,y:b.y+b.vy/speed*step,floorId:b.floorId},wall=this.nav.cast(b,end);let nearest=wall.wall?wall.t:1.00001,target=null,head=false;for(const bound of this.actorHash.query(Math.min(b.x,end.x)-18,Math.min(b.y,end.y)-18,Math.abs(b.x-end.x)+36,Math.abs(b.y-end.y)+36)){const a=bound.actor;if(a.hp<=0||a.floorId!==b.floorId||(b.friendly?a===player:a!==player))continue;const body=segCircle(b.x,b.y,end.x,end.y,a.x,a.y,13),h=segCircle(b.x,b.y,end.x,end.y,a.x+Math.cos(a.angle)*11,a.y+Math.sin(a.angle)*11,7);if(h!==null&&h<nearest&&(body===null||h<=body)){nearest=h;target=a;head=true}else if(body!==null&&body<nearest){nearest=body;target=a;head=false}}
   if(target){b.travelled+=step*nearest;const w=this.defs[b.weapon],factor=1-clamp((b.travelled-w.falloffStart)/(w.range-w.falloffStart),0,1)*(1-w.minDamage),original=b.damage;b.damage*=factor;if(b.weapon==='Shotgun')b.damage/=clamp(1-b.travelled/650,.25,1);damage(target,b,head,b.x+(end.x-b.x)*nearest,b.y+(end.y-b.y)*nearest);b.damage=original;releaseBullet(i)}else if(wall.wall){this.impact(wall.x,wall.y,b.floorId);releaseBullet(i)}else{b.x=end.x;b.y=end.y;b.travelled+=step;b.remaining-=step;if(b.remaining<=0)releaseBullet(i)}
  }
 },
 timers(a,dt){a.cooldown=Math.max(0,a.cooldown-dt);a.flash=Math.max(0,a.flash-dt);a.hurt=Math.max(0,(a.hurt||0)-dt);a.recoil=Math.max(0,a.recoil-dt*.09);if(a.reload>0){a.reload=Math.max(0,a.reload-dt);if(a.reload===0){const add=Math.min(this.statsFor(a.weapon,a.mod).mag-a.ammo,a.reserve);a.ammo+=add;a.reserve-=add}}},
