 scoutHints(){if(!TZClasses.active(player,time)||player.classId!=='scout')return;ctx.save();ctx.translate(width/2,height/2);ctx.fillStyle='#76d9ef';ctx.font='12px monospace';ctx.textAlign='center';ctx.fillText('脉冲扫描',0,-38);for(const signal of TZClasses.signals(player,enemies.filter(e=>e.floorId===player.floorId),()=>false,time)){ctx.save();ctx.rotate(signal.direction);ctx.strokeStyle='#76d9ef';ctx.lineWidth=2;ctx.strokeRect(99,-4,8,8);ctx.restore()}ctx.restore()},
 soundHints(){if(!this.settings.hints||!running)return;ctx.save();ctx.translate(width/2,height/2);for(const h of this.sound.hints){const angle=h.direction*Math.PI/4,radius=Math.min(width,height)*.2;ctx.globalAlpha=clamp(h.life/.8*this.settings.strength*1.4,.0,1);ctx.strokeStyle=h.type==='GUNSHOT'?'#efbb82':h.type==='DOOR'?'#a0dbe5':'#c5d6d1';ctx.lineWidth=h.type==='GUNSHOT'?4:2;ctx.beginPath();ctx.arc(0,0,radius,angle-.18,angle+.18);ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.font='bold 15px monospace';ctx.textAlign='center';const icon=h.vertical>0?'↑':h.vertical<0?'↓':h.type==='FOOTSTEP'?'·':h.type==='DOOR'?'□':'!';ctx.fillText(icon,Math.cos(angle)*(radius+16),Math.sin(angle)*(radius+16)+5)}ctx.restore()},
