for(const [name,fn]of Object.entries({gunStats:TZTactics.gunStats,search:Expedition.search,nearby:Expedition.nearby,open:Expedition.open,install:FieldOps.install}))BuildingSweep.legacy[name]=fn;
TZTactics.gunStats=function(id,mod){return BuildingSweep.active?BuildingSweep.statsFor(id,mod):BuildingSweep.legacy.gunStats(id,mod)};
const sweepOldUpdate=update;update=function(dt){if(BuildingSweep.active&&gameMode==='solo')BuildingSweep.update(dt);else sweepOldUpdate(dt)};
const sweepOldRender=render;render=function(){if(BuildingSweep.active)BuildingSweep.render();else sweepOldRender()};
const sweepOldHUD=hud;hud=function(){if(BuildingSweep.active)BuildingSweep.hud();else sweepOldHUD()};
const sweepOldReset=reset;reset=function(options={}){BuildingSweep.active=false;document.body.classList.remove('buildingMission');BuildingSweep.audio?.stop();sweepOldReset(options)};
const sweepOldReload=reload;reload=function(){if(BuildingSweep.active)BuildingSweep.reload();else sweepOldReload()};
const sweepOldFire=fire;fire=function(a,isPlayer){return BuildingSweep.active?BuildingSweep.fire(a,isPlayer):sweepOldFire(a,isPlayer)};
const sweepOldPerceive=perceive;perceive=function(a){return BuildingSweep.active?BuildingSweep.visible(a):sweepOldPerceive(a)};
const sweepOldPickup=pickupWeapon;pickupWeapon=function(){if(BuildingSweep.active)BuildingSweep.interact();else sweepOldPickup()};
const sweepOldDrop=dropReward;dropReward=function(e){if(!BuildingSweep.active)return sweepOldDrop(e)};
const sweepOldAlert=alertEnemy;alertEnemy=function(e){if(!BuildingSweep.active)return sweepOldAlert(e);e.state='ALERT';e.alertUntil=time+BuildingSweep.difficulty.chase;e.reaction=.25;/* The bullet gives a direction, not a live player coordinate. */};
const sweepOldDamage=damage;damage=function(a,b,head,x,y){if(BuildingSweep.active){if(a.floorId!==b.floorId)return;BuildingSweep.effectFloor=a.floorId}const result=sweepOldDamage(a,b,head,x,y);if(BuildingSweep.active){BuildingSweep.effectFloor=null;if(a.hp<=0)a.state='DEAD';else if(a!==player&&b.source){a.lastKnown={x:b.source.x??x,y:b.source.y??y,floorId:a.floorId};a.repath=0}BuildingSweep.mission.remaining=aliveCount();if(!BuildingSweep.remaining&&!['EXTRACTION_AVAILABLE','EXTRACTING','MISSION_SUCCESS','MISSION_FAILED'].includes(BuildingSweep.mission.state)){BuildingSweep.mission.state='EXTRACTION_AVAILABLE';toast('区域已清空，前往撤离点',6);sound('success',.8)}}return result};
const sweepOldEmit=emit;emit=function(...args){const n=particles.length;sweepOldEmit(...args);if(BuildingSweep.active)for(let i=n;i<particles.length;i++)particles[i].floorId=BuildingSweep.effectFloor??player.floorId};
const sweepOldMark=mark;mark=function(...args){sweepOldMark(...args);if(BuildingSweep.active&&marks.length)marks[marks.length-1].floorId=BuildingSweep.effectFloor??player.floorId};
const sweepOldClear=clearInput;clearInput=function(){sweepOldClear();if(typeof ControlUI!=='undefined')ControlUI.drag=null;for(const el of document.querySelectorAll?.('[data-sweep-pressed]')||[]){el.removeAttribute('data-sweep-pressed');el.classList.remove('pressed')}};
Expedition.nearby=function(){if(!BuildingSweep.active)return BuildingSweep.legacy.nearby.call(this);let best=null,d=64;for(const c of this.containers){if(c.opened||c.floorId!==player.floorId)continue;const n=dist(c,player);if(n<d&&BuildingSweep.nav.los(player,c)){d=n;best=c}}return best};
Expedition.search=function(){if(BuildingSweep.active)BuildingSweep.interact();else BuildingSweep.legacy.search.call(this)};
Expedition.open=function(c){if(!BuildingSweep.active)return BuildingSweep.legacy.open.call(this,c);if(c.opened||this.bag.length>=8)return false;c.opened=true;c.progress=0;this.bag.push('intel');BuildingSweep.emit('DOOR',player,180,.3);toast('已收集建筑档案 · 撤离后存入仓库');return true};
FieldOps.install=function(){if(BuildingSweep.active)BuildingSweep.install();else BuildingSweep.legacy.install.call(this)};
const sweepOldScreen=showScreen;showScreen=function(name){if(['home','network','exited'].includes(name)){BuildingSweep.active=false;document.body.classList.remove('buildingMission');BuildingSweep.audio?.stop()}sweepOldScreen(name);if(['home','sweepweapons'].includes(name))window.TZApplyBuildingUpdate?.()};
const sweepOldSkill=ClassUI.cast;ClassUI.cast=function(){if(!BuildingSweep.active)return sweepOldSkill.call(this);if(!running||paused||editing||player.hp<=0||player.skillReadyAt>time)return;const hp=player.hp;if(player.classId==='supplier'){const w=BuildingSweep.defs[player.weapon],add=Math.min(w.magazineSize,Math.max(0,w.reserveAmmo*2-player.reserve));if(!add){toast('备弹已满');return}player.reserve+=add;player.skillReadyAt=time+38;player.skillCastAt=time;toast('弹药支援 · +'+add+' 发')}else sweepOldSkill.call(this);stats.healed+=Math.max(0,player.hp-hp);if(player.classId!=='infiltrator')BuildingSweep.emit('ENEMY_VOICE',player,300,.4)};
const sweepOldShare=shareText;shareText=function(r){const b=BuildingSweep.result;if(!b||r?.mapName!==b.mapName)return sweepOldShare(r);return `TACTICAL ZERO 4.0 / BUILDING SWEEP\n${b.mapName} · ${TZBuildingData.DIFFICULTIES[b.difficulty].label}\n${b.won?'撤离成功':'行动失败'} · ${BuildingSweep.defs[b.weapon].name}\n击杀 ${b.kills} · 命中 ${b.accuracy}% · 承伤 ${Math.round(b.damageTaken)}\n时间 ${clockText(b.elapsed)} · ${b.noDamage?'无伤':'受伤'}\n最佳 ${b.best?clockText(b.best):'—'}`};
const sweepOldSound=sound,sweepUISounds=[];sound=function(type,volume=1){if(BuildingSweep.active){if(BuildingSweep.settings.sfx<=0)return;const now=audio?.currentTime||0;for(let i=sweepUISounds.length-1;i>=0;i--)if(sweepUISounds[i]<=now)sweepUISounds.splice(i,1);if(sweepUISounds.length>=(['success','death','extract'].includes(type)?8:6))return;sweepUISounds.push(now+(SOUNDS[type]||SOUNDS.hit)[2]);volume*=BuildingSweep.settings.sfx}sweepOldSound(type,volume)};
